  let top = Point(x, y - height)
  let left = Point(x - 40, y - height + 20)
  let front = Point(x, y - height + 40)
  let right = Point(x + 40, y - height + 20)
  let base_left = Point(x - 40, y + 20)
  let base_front = Point(x, y + 40)
